-- 자동 생성 파일. 직접 고치지 않는다 (scripts/gen-dev-seed.mts).
-- 개발용 코스 3개. application-dev.yaml에서만 이 위치를 읽는다. 여러 번 적용해도 한 번만 들어간다.
-- 경로: © OpenStreetMap contributors (ODbL 1.0). 고도: Open-Meteo Elevation API (Copernicus DEM 90m).

VALUES ('SYSTEM', 'local-seed', '달리모', 'LOCALSEED', 'ACTIVE', NOW(3), NOW(3));
SET @creator := (SELECT id FROM tbl_user WHERE provider = 'SYSTEM' AND provider_user_id = 'local-seed');

-- 수성못 둘레길: 1909m, 경로 point 193개
SELECT @creator, '수성못 둘레길', '수성못을 한 바퀴 도는 평지 루프. 호숫가 산책로라 신호가 없고, 밤에도 조명이 밝아 퇴근 후 달리기 좋아요.', 1909, 35.8284400, 128.6213000, 35.8284400, 128.6213000, 9.00, 'EASY', 'VERIFIED', 'PUBLIC', NOW(3), NOW(3) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_course WHERE creator_id = @creator AND name = '수성못 둘레길');
SET @course := (SELECT id FROM tbl_course WHERE creator_id = @creator AND name = '수성못 둘레길');

-- 신천 강변 왕복: 4647m, 경로 point 467개
SELECT @creator, '신천 강변 왕복', '신천 동쪽 강변을 따라 남쪽으로 내려갔다 돌아오는 왕복. 자전거 도로와 나뉘어 있어요.', 4647, 35.8440300, 128.6081600, 35.8440300, 128.6081600, 32.00, 'MODERATE', 'VERIFIED', 'PUBLIC', NOW(3), NOW(3) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_course WHERE creator_id = @creator AND name = '신천 강변 왕복');
SET @course := (SELECT id FROM tbl_course WHERE creator_id = @creator AND name = '신천 강변 왕복');

-- 들안로 왕복: 2220m, 경로 point 224개
SELECT @creator, '들안로 왕복', '수성못 북쪽에서 들안로를 따라 올라갔다 돌아오는 왕복 코스. 인도가 넓고 오르막이 거의 없어요.', 2220, 35.8301400, 128.6167600, 35.8301400, 128.6167600, 6.00, 'EASY', 'VERIFIED', 'PUBLIC', NOW(3), NOW(3) FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM tbl_course WHERE creator_id = @creator AND name = '들안로 왕복');
SET @course := (SELECT id FROM tbl_course WHERE creator_id = @creator AND name = '들안로 왕복');
